#include <iostream>
#include <sstream>
#include <string>
#include "boost/algorithm/string.hpp"

using namespace std;

string convert_markdown_to_html(const string& input) {
    // Convert line-breaks to spaces for easier processing
    string modified_input = input;
    boost::replace_all(modified_input, "\n", " ");

    // Declare stringstream object to hold HTML output
    stringstream ss_output;

    int level = 0; // Track nesting level for list items and block quotes

    bool in_list_item = false; // Flag when in a list item context

    for (const auto& c : modified_input) {
        switch (c) {
            case '#': { // Heading
                if (++level > 6) break; // Limit heading hierarchy to h1-h6
                ss_output << "<h" << level << ">";
                break;
            }
            case '*':
                if (!in_list_item &&!level) { // Start new unordered list
                    ss_output << "<ul>";
                    ++in_list_item;
                } else if (in_list_item) { // New bullet point within existing list
                    ss_output << "<li>";
                }
            case '-':
                ss_output << "<li>"; // Start new ordered or unordered list item
                break;
            case '`':
                ss_output << "<pre><code>";
                break;
            case '|':
                ss_output << "</code></pre><table>";
                break;
            case '[':
                ss_output << "<a href=\"";
                break;
            case ']':
                ss_output << "\">";
                break;
            case '(':
                ss_output << "&lt;";
                break;
            case ')':
                ss_output << "&gt;";
                break;
            case '\\':
                ss_output << "\\ ";
                break;
            default:
                ss_output << c;
        }
    }

    // Close any open elements and finalize the output stream
    while (level--) ss_output << "</p>";
    if (in_list_item) ss_output << "</ul>";
    ss_output << "</div>";

    return ss_output.str();
}

int main() {
    string markdown_text = "Hello World!\n\nThis is a **bold** text.\n\n# H1 header\n## H2 header\n### H3 header\n##### H4 header\n###### H5 header\n####### H6 header\n\n* Unordered List Item 1\n- Ordered List Item 1\n   * Nested UL Item 1\n     - Nested OL Item 1\n       | Tabular Data |\n       |:-------------:|\n       | First column | Second Column |\n       | -----------  | -------------- |\n       | Third col.  | Fourth Col.   |\n\n```\nCode Block\n```\n\n[Link Text](https://example.com)\n\n_Italicized text_\n\n`Inline code`\n\n> Block quote\n\"Double-quote\"\n\n![Alt Text](https://example.com/image.jpg)";
    string html_text = convert_markdown_to_html(markdown_text);
    cout << "Markdown:\n" << markdown_text << endl;
    cout << "HTML:\n" << html_text << endl;
    return 0;
}
``` 

Note that this implementation uses the Boost.CString library to simplify some regular expression-based logic for parsing tab-delimited tables, but this dependency can be excluded by replacing those parts with custom regular expressions or algorithms. Also note that this implementation assumes certain conventions for formatting links, italicization, inline code, block quotes and image URLs, which may vary between different Markdown implementations. To support other syntax variations, additional cases should be added to the `switch` statement accordingly.user

