Here's an example C++ program that reads a text file named "input.txt" line-by-line, searches for a specified word ("hello") using the `std::string` class, and counts the number of times it appears in the file.

```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    // open input file and fail if can't be opened
    ifstream inputFile("input.txt");
    if (!inputFile) {
        cout << "Error: could not open input file." << endl;
        return 1;
    }

    string line;
    int count = 0;

    // loop through each line of the file, searching for target word
    while (getline(inputFile, line)) {
        size_t pos = line.find("hello"); // find first occurrence of target word
        while (pos!= string::npos) { // keep finding subsequent occurrences until none left
            count++;
            pos = line.find("hello", pos + 1); // advance search to next position
        }
    }

    // close the input file and print output count
    inputFile.close();
    cout << "Target word appears " << count << " times in input file." << endl;
    return 0;
}
```

Note that this program assumes the file is formatted with newlines (\n) at the end of each line, which allows `std::filesystem::ifstream` to read individual lines with the `getline()` function. Additionally, the program doesn't handle any error cases outside of opening the input file, so you may want to add more robustness depending on your needs.user

