function binarySearch(arr, target) {
  let left = 0;
  let right = arr.length - 1;

  while (left <= right) {
    const middle = Math.floor((left + right) / 2);

    if (arr[middle] === target) {
      return true; // found target
    } else if (arr[middle] < target) {
      left = middle + 1; // search right half
    } else {
